# hx-used: search y (x0-32) as (wp'(P1)/wp'(P2)) * (wp(P3)-wp(P4))/(wp(P5)-wp(P4)) * F(x) on L16 = <1/16, tau>,
# points P in the subgroup generated by 1/32 and tau/8 (mod +-).
import itertools, sys
from mpmath import mp, mpf, mpc, exp, pi, jtheta, diff
mp.dps = 40
I = mpc(0, 1)

def eta(t):
    q = exp(2*pi*I*t); p = mpc(1); n = 1
    while True:
        term = q**n; p *= (1 - term)
        if abs(term) < mpf(10)**(-45): break
        n += 1
    return exp(pi*I*t/12)*p

def xC(t): return eta(2*t)**2*eta(16*t)/(eta(4*t)*eta(32*t)**2) + 2
def yC(t): return -eta(8*t)**4*eta(16*t)**2/(eta(4*t)**2*eta(32*t)**4)

def wp(z, T):
    q = exp(pi*I*T)
    t2 = jtheta(2, 0, q); t3 = jtheta(3, 0, q)
    return (pi*t2*t3*jtheta(4, pi*z, q)/jtheta(1, pi*z, q))**2 - pi**2/3*(t2**4 + t3**4)

def wpd(z, T):
    q = exp(pi*I*T)
    t2 = jtheta(2, 0, q); t3 = jtheta(3, 0, q)
    f = lambda u: pi*t2*t3*jtheta(4, pi*u, q)/jtheta(1, pi*u, q)
    return 2*f(z)*diff(f, z)

def wp16(z, t): return 256*wp(16*z, 16*t)
def wpd16(z, t): return 4096*wpd(16*z, 16*t)

taus = [mpc('0.1', '1.3'), mpc('-0.23', '0.71'), mpc('0.31', '0.9')]
pts = [(a, b) for a in (0, 1) for b in range(8) if (a, b) != (0, 0)]
def neg(k): return ((-k[0]) % 2, (-k[1]) % 8)
keys = []
for k in pts:
    if neg(k) not in keys: keys.append(k)
print('points (a/32 + b tau/8) mod +-:', keys)
odd = [k for k in keys if k[1] % 4 != 0]   # wp' nonzero
data = {}
for t in taus:
    P = {k: wp16(mpf(k[0])/32 + k[1]*t/8, t) for k in keys}
    D = {k: wpd16(mpf(k[0])/32 + k[1]*t/8, t) for k in odd}
    data[t] = (xC(t), yC(t), P, D)
# check wpd numerically: wpd^2 = 4 wp^3 - g2 wp - g3 consistency via two points skipped
targets = {'y': lambda x, y: y, 'y/x': lambda x, y: y/x, 'y/(x-2)': lambda x, y: y/(x-2),
           'y/(x+2)': lambda x, y: y/(x+2), 'y/(x^2+4)': lambda x, y: y/(x**2+4),
           'y/(x-2)^2': lambda x, y: y/(x-2)**2}
ratios = list(itertools.permutations(keys, 3)) + [None]
for p1, p2 in itertools.permutations(odd, 2):
    for rr in ratios:
        for name, F in targets.items():
            vals = []
            for t in taus:
                x, y, P, D = data[t]
                v = D[p1]/D[p2]
                if rr is not None:
                    v *= (P[rr[0]] - P[rr[1]])/(P[rr[2]] - P[rr[1]])
                vals.append(v/F(x, y))
            if abs(vals[0]) > mpf(10)**-10 and all(abs(v - vals[0]) < mpf(10)**-20 for v in vals):
                print(name, '= c *', (p1, p2), rr, 'c =', mp.nstr(vals[0], 15))
